import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

softplus_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void softplus_kernel(const float* x, float* out, int size) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        const float val = x[idx];
        if (val > 20.0f) {
            out[idx] = val;
        } else if (val < -15.0f) {
            out[idx] = expf(val);
        } else {
            out[idx] = log1pf(expf(val));
        }
    }
}

torch::Tensor softplus_cuda(torch::Tensor x) {
    auto out = torch::empty_like(x);
    const int64_t size = x.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    softplus_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );

    return out;
}
"""

softplus_cpp_source = "torch::Tensor softplus_cuda(torch::Tensor x);"

softplus_ext = load_inline(
    name='softplus_ext',
    cpp_sources=softplus_cpp_source,
    cuda_sources=softplus_source,
    functions=['softplus_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.softplus_op = softplus_ext.softplus_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.softplus_op(x)
